WITH lines AS (SELECT id, customer_id, created_at, key, value FROM carts LATERAL VIEW OUTER EXPLODE(attributes) e AS key, value) SELECT key, DATE_TRUNC('DAY', created_at) AS activity_day, customer_id, COUNT_IF(key = 'gift') AS gift_events, COUNT(*) AS cnt, COUNT_IF(key = 'utm_source') AS utm_source_events, COUNT_IF(key = 'gift') AS gift_events_2, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, COUNT(*) AS cnt_2 FROM lines GROUP BY key, activity_day, customer_id
